{"content":"#!/usr/bin/env python3
"""Muse queue <-> GitHub sync (HTTPS only; Muse 沙盒 SSH 出唔到, 用 git 做 transport).

Bridge 直接寫 pending/ 落 repo 工作副本；呢個 loop 負責 commit+push，
再用 pull 把 Muse 寫落嚟嘅 done/ 拉返嚟（bridge 自己會讀 done/<rid>.json）。

Loop: 每 2 秒 pull 一次；有 queue/ 改動就 commit+push。
Muse 側只需要 `git pull`（5 秒一次）就見到新單，`git push` 交答案。
"""
import fcntl, pathlib, subprocess, time

REPO = pathlib.Path("/home/ubuntu/muse-bridge/repo")
INTERVAL = 2


def git(*args, timeout=60):
    return subprocess.run(["git", *args], cwd=REPO, capture_output=True,
                          text=True, timeout=timeout)


def tick(lock):
    # 先拉（Muse 交嘅 done 檔）；rebase 失敗（衝突）就 abort 等下一輪
    r = git("pull", "--rebase", "--autostash", "-q")
    if r.returncode != 0 and "fatal" in (r.stderr or "").lower():
        git("rebase", "--abort")

    if not git("status", "--porcelain", "--", "queue").stdout.strip():
        return
    git("add", "-A", "queue")
    c = git("commit", "-q", "-m", f"queue: hermes {time.strftime('%H:%M:%S')}")
    if c.returncode != 0:
        return
    p = git("push", "-q", "origin", "HEAD")
    if p.returncode != 0:
        print("push failed:", p.stderr.strip()[:200], flush=True)


if __name__ == "__main__":
    print("muse-git-sync watching", REPO / "queue", flush=True)
    with open("/home/ubuntu/muse-bridge/repo/.git-sync.lock", "w") as lf:
        while True:
            try:
                fcntl.flock(lf, fcntl.LOCK_EX | fcntl.LOCK_NB)
                tick(lf)
                fcntl.flock(lf, fcntl.LOCK_UN)
            except BlockingIOError:
                pass                     # 另一輪／cron poll.py 用緊 index
            except Exception as e:
                print("tick error:", e, flush=True)
            time.sleep(INTERVAL)
